item.text:
{
  "packet_id": "H6-T06-2",
  "claims": [
    {
      "claim_id": "C001",
      "fields": ["state"],
      "component": {
        "component_id": "C001.component",
        "value": "The conflicting branch evidence is provisionally treated as a mixture of distinguishable demand components, including weekday-served needs, potentially weekend-served needs, and needs constrained by access barriers; these components are hypotheses rather than established groups.",
        "scope": "Both branches; the listed components are examples, and their distinguishability is hypothetical.",
        "provenance": {
          "refs": [
            {"source_id": "P001", "role": "SUPPORT"},
            {"source_id": "P002", "role": "SUPPORT"}
          ],
          "support_status": "SUFFICIENT",
          "rationale": "The bundle supplies the proposed mixture, examples, and explicit hypothetical status."
        }
      }
    },
    {
      "claim_id": "C002",
      "fields": ["state"],
      "component": {
        "component_id": "C002.component",
        "value": "Recurring opening opportunities through which potential visits can proceed serve as the moving-phase counterpart.",
        "scope": "An assigned correspondence within the transfer.",
        "provenance": {
          "refs": [{"source_id": "P003", "role": "SUPPORT"}],
          "support_status": "SUFFICIENT",
          "rationale": "The span directly assigns this counterpart."
        }
      }
    },
    {
      "claim_id": "C003",
      "fields": ["state"],
      "component": {
        "component_id": "C003.component",
        "value": "Relatively persistent access constraints that can delay or prevent participation serve as the stationary-phase counterpart.",
        "scope": "Relative persistence and possible effects on participation qualify the correspondence.",
        "provenance": {
          "refs": [{"source_id": "P003", "role": "SUPPORT"}],
          "support_status": "SUFFICIENT",
          "rationale": "The span supplies the counterpart and its qualifying properties."
        }
      }
    },
    {
      "claim_id": "C004",
      "fields": ["state"],
      "component": {
        "component_id": "C004.component",
        "value": "Repeated exposure to opening opportunities is assumed capable of producing different uptake patterns.",
        "scope": "A stated possibility assumed for the transfer, not an observed result or guaranteed effect.",
        "provenance": {
          "refs": [
            {"source_id": "P004", "role": "SUPPORT"},
            {"source_id": "P003", "role": "CONTEXT"}
          ],
          "support_status": "SUFFICIENT",
          "rationale": "P004 states the assumption; P003 resolves the opening opportunities."
        }
      }
    },
    {
      "claim_id": "C005",
      "fields": ["state"],
      "component": {
        "component_id": "C005.component",
        "value": "Attendance and stated unmet need need not vary together.",
        "scope": "Possible divergence between attendance and reported need; no direction or magnitude is asserted.",
        "provenance": {
          "refs": [{"source_id": "P004", "role": "SUPPORT"}],
          "support_status": "SUFFICIENT",
          "rationale": "The span explicitly states their possible divergence."
        }
      }
    },
    {
      "claim_id": "C006",
      "fields": ["operation"],
      "component": {
        "component_id": "C006.component",
        "value": "The proposed intervention is a reversible three-month trial at both branches that transfers specified weekday opening blocks to specified weekend blocks.",
        "scope": "A bounded proposal, not an assertion of completed implementation or demonstrated feasibility; the actual blocks are not identified.",
        "provenance": {
          "refs": [{"source_id": "P005", "role": "SUPPORT"}],
          "support_status": "SUFFICIENT",
          "rationale": "The span supplies the proposal, duration, locations, transfer, and reversibility requirement."
        }
      }
    },
    {
      "claim_id": "C007",
      "fields": ["operation"],
      "component": {
        "component_id": "C007.component",
        "value": "Launch requires checking that coverage, pay premiums, preparation, and recovery time fit the existing staffing budget; an infeasible schedule must not launch.",
        "scope": "A pre-launch feasibility gate, not a finding that the proposed schedule satisfies it.",
        "provenance": {
          "refs": [{"source_id": "P006", "role": "SUPPORT"}],
          "support_status": "SUFFICIENT",
          "rationale": "The span states the required checks and the prohibition on an infeasible launch."
        }
      }
    },
    {
      "claim_id": "C008",
      "fields": ["operation"],
      "component": {
        "component_id": "C008.component",
        "value": "The trial's pre-trial measurements should be established on a comparable basis.",
        "scope": "A measurement-design requirement; the mapping does not specify a comparability test.",
        "provenance": {
          "refs": [{"source_id": "P008", "role": "SUPPORT"}],
          "support_status": "SUFFICIENT",
          "rationale": "The span explicitly requires comparable pre-trial measurements."
        }
      }
    },
    {
      "claim_id": "C009",
      "fields": ["operation", "limit"],
      "component": {
        "component_id": "C009.component",
        "value": "Unchanged opening windows, where available, can provide contextual comparisons for the trial.",
        "scope": "Contextual comparison status only; their availability is conditional.",
        "provenance": {
          "refs": [
            {"source_id": "P008", "role": "SUPPORT"},
            {"source_id": "P031", "role": "SUPPORT"}
          ],
          "support_status": "SUFFICIENT",
          "rationale": "Both spans assign a contextual role, and P008 supplies the availability condition."
        }
      }
    },
    {
      "claim_id": "C010",
      "fields": ["operation"],
      "component": {
        "component_id": "C010.component",
        "value": "Across repeated weekly exposure to the trial schedule, potential visits may become attendance or remain deferred or unserved.",
        "scope": "Possible outcomes during weekly cycles, not claims that any particular outcome has occurred.",
        "provenance": {
          "refs": [{"source_id": "P009", "role": "SUPPORT"}],
          "support_status": "SUFFICIENT",
          "rationale": "The span states the repeated exposure and alternative possible outcomes."
        }
      }
    },
    {
      "claim_id": "C011",
      "fields": ["operation"],
      "component": {
        "component_id": "C011.component",
        "value": "Repeated weekly exposure, with potential visits proceeding into attendance or remaining deferred or unserved, is the counterpart of repeated partitioning.",
        "scope": "An operational correspondence, without asserting literal physical partitioning.",
        "provenance": {
          "refs": [{"source_id": "P009", "role": "SUPPORT"}],
          "support_status": "SUFFICIENT",
          "rationale": "The span explicitly assigns the partitioning correspondence to this process."
        }
      }
    },
    {
      "claim_id": "C012",
      "fields": ["operation"],
      "component": {
        "component_id": "C012.component",
        "value": "The schedule should remain stable within each assessment period.",
        "scope": "A within-period operating requirement; it does not prohibit adjustments between periods.",
        "provenance": {
          "refs": [{"source_id": "P010", "role": "SUPPORT"}],
          "support_status": "SUFFICIENT",
          "rationale": "The span gives the stability requirement and its period boundary."
        }
      }
    },
    {
      "claim_id": "C013",
      "fields": ["operation"],
      "component": {
        "component_id": "C013.component",
        "value": "Access associated with removed weekday blocks is to be assessed through baseline use and subsequent reports of lost access.",
        "scope": "A proposed measurement approach, without claiming that either source alone completely measures weekday losses.",
        "provenance": {
          "refs": [{"source_id": "P012", "role": "SUPPORT"}],
          "support_status": "SUFFICIENT",
          "rationale": "The span identifies both evidence sources for assessing removed blocks."
        }
      }
    },
    {
      "claim_id": "C014",
      "fields": ["operation"],
      "component": {
        "component_id": "C014.component",
        "value": "Explicit numerical criteria for meaningful access gains, tolerable weekday access loss, and staff workload must be set before launch.",
        "scope": "Precommitment of decision criteria; the mapping supplies no numerical thresholds.",
        "provenance": {
          "refs": [{"source_id": "P013", "role": "SUPPORT"}],
          "support_status": "SUFFICIENT",
          "rationale": "The span supplies the timing, numerical form, categories, and absence of values."
        }
      }
    },
    {
      "claim_id": "C015",
      "fields": ["operation"],
      "component": {
        "component_id": "C015.component",
        "value": "The packet does not provide values for the required numerical decision criteria.",
        "scope": "An explicit incompleteness of the proposed decision procedure; no values are inferred.",
        "provenance": {
          "refs": [{"source_id": "P013", "role": "SUPPORT"}],
          "support_status": "SUFFICIENT",
          "rationale": "The absence of supplied values is expressly stated."
        }
      }
    },
    {
      "claim_id": "C016",
      "fields": ["operation", "inference"],
      "component": {
        "component_id": "C016.component",
        "value": "A schedule adjustment is to be treated as a new operating condition.",
        "scope": "Any adjustment; revised conditions must remain distinct in the assessment.",
        "provenance": {
          "refs": [
            {"source_id": "P015", "role": "SUPPORT"},
            {"source_id": "P024", "role": "SUPPORT"}
          ],
          "support_status": "SUFFICIENT",
          "rationale": "P015 states the rule, and P024 describes changed blocks as revised conditions."
        }
      }
    },
    {
      "claim_id": "C017",
      "fields": ["signal"],
      "component": {
        "component_id": "C017.component",
        "value": "Candidate signals are recurring time-and-condition differences in observable demand, including weekend uptake, concentration near transport arrivals or programs, delayed uptake across weeks, continued weekday use, and persistent inability-to-attend reports.",
        "scope": "Patterns to look for, not established observations or an exhaustive classification of needs.",
        "provenance": {
          "refs": [{"source_id": "P016", "role": "SUPPORT"}],
          "support_status": "SUFFICIENT",
          "rationale": "The span identifies the proposed signal family and its examples."
        }
      }
    },
    {
      "claim_id": "C018",
      "fields": ["signal"],
      "component": {
        "component_id": "C018.component",
        "value": "The demand profiles organized by time and conditions serve as counterparts of separated bands or peaks.",
        "scope": "A correspondence assigned to the candidate profiles, not proof that demand components have actually separated.",
        "provenance": {
          "refs": [
            {"source_id": "P017", "role": "SUPPORT"},
            {"source_id": "P016", "role": "CONTEXT"}
          ],
          "support_status": "SUFFICIENT",
          "rationale": "P017 states the correspondence; P016 identifies the referenced profiles."
        }
      }
    },
    {
      "claim_id": "C019",
      "fields": ["signal"],
      "component": {
        "component_id": "C019.component",
        "value": "Relative delay before uptake serves as the retention counterpart.",
        "scope": "The correspondence leaves the delay's reference point and calculation unspecified.",
        "provenance": {
          "refs": [{"source_id": "P017", "role": "SUPPORT"}],
          "support_status": "SUFFICIENT",
          "rationale": "The span directly identifies relative uptake delay with the retention counterpart."
        }
      }
    },
    {
      "claim_id": "C020",
      "fields": ["signal"],
      "component": {
        "component_id": "C020.component",
        "value": "Reporting should distinguish branches, program from ordinary visits, and term and transport conditions where sample sizes permit.",
        "scope": "Conditional disaggregation; adequate sample sizes are required but not numerically defined.",
        "provenance": {
          "refs": [{"source_id": "P018", "role": "SUPPORT"}],
          "support_status": "SUFFICIENT",
          "rationale": "The span supplies the distinctions and sample-size qualification."
        }
      }
    },
    {
      "claim_id": "C021",
      "fields": ["signal"],
      "component": {
        "component_id": "C021.component",
        "value": "Program attendance must not be added to door counts when the same visits may occur in both measures.",
        "scope": "The restriction applies where double counting is possible; it does not assert that every program visit is duplicated.",
        "provenance": {
          "refs": [{"source_id": "P020", "role": "SUPPORT"}],
          "support_status": "SUFFICIENT",
          "rationale": "The span states the aggregation restriction and its condition."
        }
      }
    },
    {
      "claim_id": "C022",
      "fields": ["signal"],
      "component": {
        "component_id": "C022.component",
        "value": "An unobserved visit cannot be interpreted as directly measured unmet demand.",
        "scope": "A restriction on interpreting non-observation, not a denial that unmet demand may exist.",
        "provenance": {
          "refs": [{"source_id": "P020", "role": "SUPPORT"}],
          "support_status": "SUFFICIENT",
          "rationale": "The span explicitly rejects this measurement interpretation."
        }
      }
    },
    {
      "claim_id": "C023",
      "fields": ["inference"],
      "component": {
        "component_id": "C023.component",
        "value": "Repeatable differences in uptake or continued deferral would support distinguishable access-response components under the trial schedule.",
        "scope": "Conditional evidential support under this schedule, not unconditional establishment of demand groups.",
        "provenance": {
          "refs": [{"source_id": "P021", "role": "SUPPORT"}],
          "support_status": "SUFFICIENT",
          "rationale": "The span supplies the repeatability condition, proposed inference, and schedule restriction."
        }
      }
    },
    {
      "claim_id": "C024",
      "fields": ["inference"],
      "component": {
        "component_id": "C024.component",
        "value": "Repeatable differences in uptake or continued deferral would permit characterization of access-response components' relative responsiveness or delay under the trial schedule.",
        "scope": "Conditional characterization of relative response under this schedule.",
        "provenance": {
          "refs": [{"source_id": "P021", "role": "SUPPORT"}],
          "support_status": "SUFFICIENT",
          "rationale": "The span separately attributes relative-response characterization to the repeatable differences."
        }
      }
    },
    {
      "claim_id": "C025",
      "fields": ["inference"],
      "component": {
        "component_id": "C025.component",
        "value": "Convergent voluntary reports can help distinguish newly enabled access from visits shifted from weekdays.",
        "scope": "Convergence and voluntary reporting qualify a contributory distinction, not definitive identification.",
        "provenance": {
          "refs": [{"source_id": "P022", "role": "SUPPORT"}],
          "support_status": "SUFFICIENT",
          "rationale": "The span gives the evidence condition, distinction, and limited strength."
        }
      }
    },
    {
      "claim_id": "C026",
      "fields": ["inference"],
      "component": {
        "component_id": "C026.component",
        "value": "Keeping the trial schedule requires meeting the precommitted access-gain criterion.",
        "scope": "One necessary condition in a conjunctive retention rule; it is not independently sufficient.",
        "provenance": {
          "refs": [{"source_id": "P023", "role": "SUPPORT"}],
          "support_status": "SUFFICIENT",
          "rationale": "The only-if formulation makes this a necessary condition alongside the other requirements."
        }
      }
    },
    {
      "claim_id": "C027",
      "fields": ["inference"],
      "component": {
        "component_id": "C027.component",
        "value": "Keeping the trial schedule requires weekday access losses to remain within their limits.",
        "scope": "One necessary condition in a conjunctive retention rule; it is not independently sufficient.",
        "provenance": {
          "refs": [{"source_id": "P023", "role": "SUPPORT"}],
          "support_status": "SUFFICIENT",
          "rationale": "The span expressly includes acceptable weekday losses among the necessary conditions."
        }
      }
    },
    {
      "claim_id": "C028",
      "fields": ["inference"],
      "component": {
        "component_id": "C028.component",
        "value": "Keeping the trial schedule requires staff workload to remain within its limits.",
        "scope": "One necessary condition in a conjunctive retention rule; it is not independently sufficient.",
        "provenance": {
          "refs": [{"source_id": "P023", "role": "SUPPORT"}],
          "support_status": "SUFFICIENT",
          "rationale": "The span expressly includes workload limits among the necessary conditions."
        }
      }
    },
    {
      "claim_id": "C029",
      "fields": ["inference"],
      "component": {
        "component_id": "C029.component",
        "value": "Keeping the trial schedule requires continued budget feasibility.",
        "scope": "One necessary condition in a conjunctive retention rule; it is not independently sufficient.",
        "provenance": {
          "refs": [{"source_id": "P023", "role": "SUPPORT"}],
          "support_status": "SUFFICIENT",
          "rationale": "The span requires the budget to remain feasible for retention."
        }
      }
    },
    {
      "claim_id": "C030",
      "fields": ["inference"],
      "component": {
        "component_id": "C030.component",
        "value": "Particular opening blocks should be changed if a reproducible profile suggests a better allocation.",
        "scope": "A conditional adjustment rule; a suggested improvement is not asserted to be a demonstrated improvement.",
        "provenance": {
          "refs": [{"source_id": "P024", "role": "SUPPORT"}],
          "support_status": "SUFFICIENT",
          "rationale": "The span supplies the reproducibility condition and the proposed response."
        }
      }
    },
    {
      "claim_id": "C031",
      "fields": ["inference"],
      "component": {
        "component_id": "C031.component",
        "value": "Changing blocks on the basis of a suggested better allocation requires stating the hypothesis and measuring again under the revised conditions.",
        "scope": "Applies to the proposed adjustment process; the revised allocation remains subject to renewed measurement.",
        "provenance": {
          "refs": [{"source_id": "P024", "role": "SUPPORT"}],
          "support_status": "SUFFICIENT",
          "rationale": "The span couples adjustment with an explicit hypothesis and renewed measurement."
        }
      }
    },
    {
      "claim_id": "C032",
      "fields": ["operation", "inference"],
      "component": {
        "component_id": "C032.component",
        "value": "A breach of a pre-established immediate safety or coverage stopping rule requires stopping the trial or restoring the original schedule.",
        "scope": "An immediate response to a stopping-rule breach; the mapping leaves stopping versus restoration as alternatives.",
        "provenance": {
          "refs": [
            {"source_id": "P025", "role": "SUPPORT"},
            {"source_id": "P013", "role": "SUPPORT"}
          ],
          "support_status": "SUFFICIENT",
          "rationale": "P025 supplies the conditional response; P013 supplies the rule categories and pre-launch establishment."
        }
      }
    },
    {
      "claim_id": "C033",
      "fields": ["inference"],
      "component": {
        "component_id": "C033.component",
        "value": "At the final review, failure of gains to meet the agreed criterion requires stopping the trial or restoring the original schedule.",
        "scope": "A final-review outcome relation; no numerical gain criterion or choice between the two responses is supplied.",
        "provenance": {
          "refs": [
            {"source_id": "P025", "role": "SUPPORT"},
            {"source_id": "P013", "role": "SUPPORT"}
          ],
          "support_status": "SUFFICIENT",
          "rationale": "P025 states the trigger and response, while P013 expressly leaves criterion values unspecified."
        }
      }
    },
    {
      "claim_id": "C034",
      "fields": ["inference"],
      "component": {
        "component_id": "C034.component",
        "value": "At the final review, harms exceeding their limits require stopping the trial or restoring the original schedule.",
        "scope": "A final-review outcome relation. The term harms is not exhaustively defined; numerical limits and the choice between stopping and restoration remain unspecified.",
        "provenance": {
          "refs": [
            {"source_id": "P025", "role": "SUPPORT"},
            {"source_id": "P013", "role": "SUPPORT"}
          ],
          "support_status": "SUFFICIENT",
          "rationale": "P025 states the harm-triggered response; P013 identifies loss and workload criteria without supplying values."
        }
      }
    },
    {
      "claim_id": "C035",
      "fields": ["inference"],
      "component": {
        "component_id": "C035.component",
        "value": "If evidence remains inconclusive, the original schedule should be restored unless a further bounded trial is explicitly authorized.",
        "scope": "The exception requires explicit authorization of a bounded further trial; inconclusiveness alone does not authorize continuation.",
        "provenance": {
          "refs": [{"source_id": "P026", "role": "SUPPORT"}],
          "support_status": "SUFFICIENT",
          "rationale": "The span supplies the condition, default response, and authorization exception."
        }
      }
    },
    {
      "claim_id": "C036",
      "fields": ["limit"],
      "component": {
        "component_id": "C036.component",
        "value": "Different needs can yield the same attendance profile, which is treated as analogous to co-elution.",
        "scope": "Possible observational overlap; distinct needs need not produce distinct profiles.",
        "provenance": {
          "refs": [{"source_id": "P027", "role": "SUPPORT"}],
          "support_status": "SUFFICIENT",
          "rationale": "The span states the overlap and its co-elution correspondence."
        }
      }
    },
    {
      "claim_id": "C037",
      "fields": ["limit"],
      "component": {
        "component_id": "C037.component",
        "value": "One person can contribute to several attendance profiles.",
        "scope": "Possible overlap in profile membership; profiles need not correspond to mutually exclusive people.",
        "provenance": {
          "refs": [{"source_id": "P027", "role": "SUPPORT"}],
          "support_status": "SUFFICIENT",
          "rationale": "The span explicitly permits one person to contribute to multiple profiles."
        }
      }
    },
    {
      "claim_id": "C038",
      "fields": ["signal", "limit"],
      "component": {
        "component_id": "C038.component",
        "value": "Transport changes, school terms, programming, weather, and adjustment time can shift apparent uptake delay, the retention counterpart.",
        "scope": "Possible condition-dependent shifts; no direction, magnitude, or demonstrated effect is specified.",
        "provenance": {
          "refs": [
            {"source_id": "P028", "role": "SUPPORT"},
            {"source_id": "P017", "role": "SUPPORT"}
          ],
          "support_status": "SUFFICIENT",
          "rationale": "P028 supplies the possible shifts and factors; P017 supplies the meaning of retention in the transfer."
        }
      }
    },
    {
      "claim_id": "C039",
      "fields": ["limit"],
      "component": {
        "component_id": "C039.component",
        "value": "Door counts, program attendance, survey responses, and workload reports are nonspecific signals.",
        "scope": "A limitation of all four named evidence types; nonspecificity does not mean they contain no useful information.",
        "provenance": {
          "refs": [{"source_id": "P029", "role": "SUPPORT"}],
          "support_status": "SUFFICIENT",
          "rationale": "The span attributes nonspecificity to the named signals."
        }
      }
    },
    {
      "claim_id": "C040",
      "fields": ["limit"],
      "component": {
        "component_id": "C040.component",
        "value": "Door counts, program attendance, survey responses, and workload reports are differently selected signals.",
        "scope": "The selection differences are asserted but their mechanisms and magnitudes are not specified.",
        "provenance": {
          "refs": [{"source_id": "P029", "role": "SUPPORT"}],
          "support_status": "SUFFICIENT",
          "rationale": "The span separately attributes different selection to the evidence types."
        }
      }
    },
    {
      "claim_id": "C041",
      "fields": ["limit"],
      "component": {
        "component_id": "C041.component",
        "value": "Attendance timing alone cannot identify a demand group's needs.",
        "scope": "A limit on identification from timing alone; it does not rule out identification using additional evidence.",
        "provenance": {
          "refs": [{"source_id": "P030", "role": "SUPPORT"}],
          "support_status": "SUFFICIENT",
          "rationale": "The span expressly states this identification limit."
        }
      }
    },
    {
      "claim_id": "C042",
      "fields": ["limit"],
      "component": {
        "component_id": "C042.component",
        "value": "Attendance timing alone cannot prove previously unmet demand.",
        "scope": "A limit on establishing prior unmet demand from timing alone.",
        "provenance": {
          "refs": [{"source_id": "P030", "role": "SUPPORT"}],
          "support_status": "SUFFICIENT",
          "rationale": "The span expressly states this evidential limit."
        }
      }
    },
    {
      "claim_id": "C043",
      "fields": ["limit"],
      "component": {
        "component_id": "C043.component",
        "value": "Attendance timing alone cannot establish that the schedule caused an observed change.",
        "scope": "A causal-attribution limit applying to timing alone.",
        "provenance": {
          "refs": [{"source_id": "P030", "role": "SUPPORT"}],
          "support_status": "SUFFICIENT",
          "rationale": "The span expressly denies causal establishment from attendance timing alone."
        }
      }
    },
    {
      "claim_id": "C044",
      "fields": ["limit"],
      "component": {
        "component_id": "C044.component",
        "value": "Corroboration should be sought through direct accounts of access barriers, transport information, and comparable observation periods.",
        "scope": "A proposed corroboration approach, not a claim that these sources will necessarily converge or establish causation.",
        "provenance": {
          "refs": [{"source_id": "P031", "role": "SUPPORT"}],
          "support_status": "SUFFICIENT",
          "rationale": "The span assigns the corroborative role to these sources."
        }
      }
    },
    {
      "claim_id": "C045",
      "fields": ["limit"],
      "component": {
        "component_id": "C045.component",
        "value": "Unchanged opening windows may themselves receive visits displaced by the trial.",
        "scope": "A possible limitation of their contextual comparison role; unchanged opening hours do not ensure unchanged visit composition.",
        "provenance": {
          "refs": [{"source_id": "P031", "role": "SUPPORT"}],
          "support_status": "SUFFICIENT",
          "rationale": "The span explicitly qualifies unchanged windows with possible displaced visits."
        }
      }
    },
    {
      "claim_id": "C046",
      "fields": ["limit"],
      "component": {
